pub fn skip_whitespace(&mut self) {
    self.skip_block_at_start();
    while !self.is_eof() {
        match_byte! { self.next_byte_unchecked(),
            b' ' | b'\t' => {
                self.advance(1)
            },
            b'\n' | b'\x0C' | b'\r' => {
                self.consume_newline();
            },
            b'/' => {
                if self.starts_with(b"/*") {
                    let old = (self.source_url, self.source_map_url);
                    consume_comment(self);
                    self.source_url = old.0;
                    self.source_map_url = old.1;
                } else {
                    return
                }
            }
            _ => return,
        }
    }
}
